function sitesplat_bbinfinitepagination() {
	var selector = window['sitesplat_bbinfinitepagination_' + sitesplat_bbinfinitepagination_page];

	// mark all existing items as animated
	document.querySelectorAll(selector + ' > *').forEach(function(elem) {
		elem.classList.add('animated');
	});

	if (document.querySelector('.pagination-bottom a[rel="next"]')) {
		new InfiniteScroll(selector, {
			path: function() {
				var el = document.querySelector('.pagination-bottom a[rel="next"]');
				return el ? el.href : false;
			},
			append: selector + ' > *',
			prefill: true,
			onInit: function() {
				this.on('load', function(response) {
					// replace bottom paginations with new ones
					var newPaginations = response.querySelectorAll('.pagination-bottom');
					document.querySelectorAll('.pagination-bottom').forEach(function(elem, index) {
						elem.parentNode.replaceChild(newPaginations.item(index), elem);
					})
				});
				this.on('append', function() {
					var loader = new loader_fx(selector);
					loader._render(sitesplat_bbinfinitepagination_fx_effect);

					if (sitesplat_bblazy_blazy) {
						sitesplat_bblazy_blazy.init();
					}
				});
			}
		});
	}
}
